import base64
import json
import os
from decimal import Decimal
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _to_float(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, Decimal):
        return float(value)
    if isinstance(value, str):
        s = value.strip().replace(",", "")
        if not s:
            return None
        try:
            return float(s)
        except ValueError:
            return None
    return None


def _safe_get(d: Dict[str, Any], *keys: str) -> Any:
    cur: Any = d
    for key in keys:
        if not isinstance(cur, dict):
            return None
        cur = cur.get(key)
    return cur


def _normalize_expense(expense: Dict[str, Any]) -> Dict[str, Any]:
    line_item_groups = expense.get("LineItemGroups", []) or []
    line_items: List[Dict[str, Any]] = []

    for group in line_item_groups:
        for item in group.get("LineItems", []) or []:
            fields = item.get("LineItemExpenseFields", []) or []
            line_obj: Dict[str, Any] = {
                "description": None,
                "quantity": None,
                "unit_price": None,
                "amount": None,
                "product_code": None,
            }
            for field in fields:
                t = field.get("Type", {}) or {}
                text = _safe_get(field, "ValueDetection", "Text")
                normalized_type = (t.get("Text") or t.get("Value") or "").upper()

                if normalized_type in {"ITEM", "DESCRIPTION"}:
                    line_obj["description"] = text
                elif normalized_type in {"QUANTITY", "QTY"}:
                    line_obj["quantity"] = _to_float(text)
                elif normalized_type in {"PRICE", "UNIT_PRICE", "UNITCOST"}:
                    line_obj["unit_price"] = _to_float(text)
                elif normalized_type in {"AMOUNT", "TOTAL", "EXTENDED_PRICE"}:
                    line_obj["amount"] = _to_float(text)
                elif normalized_type in {"PRODUCT_CODE", "SKU"}:
                    line_obj["product_code"] = text

            if any(v is not None for v in line_obj.values()):
                line_items.append(line_obj)

    summary_fields = expense.get("ExpenseDocuments", [{}])[0].get("SummaryFields", []) or []
    summary: Dict[str, Any] = {
        "vendor_name": None,
        "invoice_number": None,
        "invoice_date": None,
        "due_date": None,
        "currency": None,
        "subtotal": None,
        "tax": None,
        "tip": None,
        "total": None,
        "payment_terms": None,
        "purchase_order": None,
    }

    for field in summary_fields:
        t = field.get("Type", {}) or {}
        normalized_type = (t.get("Text") or t.get("Value") or "").upper()
        text = _safe_get(field, "ValueDetection", "Text")

        if normalized_type in {"VENDOR_NAME", "SUPPLIER_NAME"}:
            summary["vendor_name"] = text
        elif normalized_type in {"INVOICE_RECEIPT_ID", "INVOICE_NUMBER", "RECEIPT_ID"}:
            summary["invoice_number"] = text
        elif normalized_type in {"INVOICE_RECEIPT_DATE", "INVOICE_DATE", "DATE"}:
            summary["invoice_date"] = text
        elif normalized_type in {"DUE_DATE"}:
            summary["due_date"] = text
        elif normalized_type in {"CURRENCY"}:
            summary["currency"] = text
        elif normalized_type in {"SUBTOTAL"}:
            summary["subtotal"] = _to_float(text)
        elif normalized_type in {"TAX"}:
            summary["tax"] = _to_float(text)
        elif normalized_type in {"TIP"}:
            summary["tip"] = _to_float(text)
        elif normalized_type in {"TOTAL"}:
            summary["total"] = _to_float(text)
        elif normalized_type in {"PAYMENT_TERMS"}:
            summary["payment_terms"] = text
        elif normalized_type in {"PO_NUMBER", "PURCHASE_ORDER"}:
            summary["purchase_order"] = text

    normalized = {
        "provider": "amazon-textract",
        "document_type": "expense",
        "vendor_name": summary["vendor_name"],
        "invoice_number": summary["invoice_number"],
        "invoice_date": summary["invoice_date"],
        "due_date": summary["due_date"],
        "currency": summary["currency"],
        "subtotal": summary["subtotal"],
        "tax": summary["tax"],
        "tip": summary["tip"],
        "total": summary["total"],
        "payment_terms": summary["payment_terms"],
        "purchase_order": summary["purchase_order"],
        "line_items": line_items,
        "raw": expense,
    }
    return normalized


def normalize_expense_fields(document_bytes: bytes, *, mime_type: str = "application/pdf") -> str:
    """
    Normalize extracted expense fields into a standard JSON schema using Amazon Textract AnalyzeExpense.
    Returns a JSON string.
    """
    textract = boto3.client("textract")
    try:
        response = textract.analyze_expense(
            Document={"Bytes": document_bytes, "S3Object": {} if False else None}  # keeps provider API explicit
        )
    except (BotoCoreError, ClientError) as exc:
        raise RuntimeError(f"Amazon Textract AnalyzeExpense failed: {exc}") from exc

    expense_docs = response.get("ExpenseDocuments", []) or []
    if not expense_docs:
        return json.dumps(
            {
                "provider": "amazon-textract",
                "document_type": "expense",
                "vendor_name": None,
                "invoice_number": None,
                "invoice_date": None,
                "due_date": None,
                "currency": None,
                "subtotal": None,
                "tax": None,
                "tip": None,
                "total": None,
                "payment_terms": None,
                "purchase_order": None,
                "line_items": [],
                "raw": response,
            },
            ensure_ascii=False,
        )

    normalized_docs = [_normalize_expense(doc) for doc in expense_docs]
    if len(normalized_docs) == 1:
        return json.dumps(normalized_docs[0], ensure_ascii=False)

    return json.dumps(
        {
            "provider": "amazon-textract",
            "document_type": "expense",
            "documents": normalized_docs,
            "raw": response,
        },
        ensure_ascii=False,
    )
